content.content:
  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import hotel.rooms.RoomType;
  5	import java.math.BigDecimal;
  6	import java.math.RoundingMode;
  7	import java.time.DayOfWeek;
  8	import java.time.LocalDate;
  9	import java.time.Month;
 10	
 11	/**
 12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 14	 * (half-even) at every step.
 15	 */
 16	public final class PriceCalculator {
 17	
 18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 20	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
 21	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
 22	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
 23	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 24	
 25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 26	        return switch (ratePlan) {
 27	            case STANDARD -> calculateStandard(room, checkIn, checkOut);
 28	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut);
 29	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 30	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 31	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 32	        };
 33	    }
 34	
 35	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut) {
 36	        int nights = 0;
 37	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 38	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 39	            subtotal = subtotal.add(nightPrice(room, night));
 40	            nights++;
 41	        }
 42	        return new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
 43	    }
 44	
 45	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut) {
 46	        int nights = 0;
 47	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 48	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 49	            subtotal = subtotal.add(nightPrice(room, night));
 50	            nights++;
 51	        }
 52	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 53	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 54	    }
 55	
 56	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 57	        int nights = 0;
 58	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 59	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 60	            subtotal = subtotal.add(nightPrice(room, night));
 61	            nights++;
 62	        }
 63	        BigDecimal discountRate = switch (companyCode) {
 64	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
 65	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
