 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        validateRatePlan(request);
 35	        Room room = rooms.find(request.roomNumber())
 36	                .orElseThrow(() -> new HotelException(
 37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 38	        if (request.guests() > room.capacity()) {
 39	            throw new HotelException(
 40	                    ErrorCode.CAPACITY_EXCEEDED,
 41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 42	        }
 43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 44	            throw new HotelException(
 45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 46	        }
 47	        try {
 48	            Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 49	            return store.add(request, price);
 50	        } catch (IllegalArgumentException planError) {
 51	            throw new HotelException(ErrorCode.INVALID_REQUEST, planError.getMessage());
 52	        }
 53	    }
