 56	        switch (request.ratePlan()) {
 57	            case CORPORATE:
 58	                if (request.companyCode() == null || request.companyCode().isBlank()) {
 59	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "corporate plan requires a company code");
 60	                }
 61	                if (!isValidCompanyCode(request.companyCode())) {
 62	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code: " + request.companyCode());
 63	                }
 64	                break;
 65	        }
 66	    }
